first, last = M[0], M[-1]
N_TMFM = sum(1 for x in A_STATUS if x[4].startswith("TM+FotMob"))
def _sub(a, b):
    r = [0, 0, 0, 0]
    for m in M:
        if a <= m[0] < b: r[0] += 1; r[3] += m[3]
    for e in E:
        if a <= e[9] < b: r[1 if e[0] == "g" else 2] += 1
    return r
